<style>
:root{--bg:#070b12;--card:#0f1724;--card2:#131d2d;--line:rgba(255,255,255,.09);--t:#f1f5f9;--m:#9aa8bb;--m2:#6b7a8f;--teal:#2ee6c5;--teal-d:#0b3b34;--gold:#d8b46a;--wa:#25d366;--r:16px}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%;scroll-padding-top:108px}
body{background:var(--bg);color:var(--t);font-family:system-ui,-apple-system,"Segoe UI",Roboto,"Noto Sans",Arial,sans-serif;font-size:15px;line-height:1.55;overflow-x:hidden}
img{display:block;max-width:100%}
a{color:inherit}
button{font:inherit;color:inherit}
.wrap{max-width:1080px;margin:0 auto;padding:0 16px}
@media(min-width:720px){.wrap{padding:0 24px}}

/* header */
.hd{position:sticky;top:0;z-index:50;background:rgba(7,11,18,.94);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}
.hd .row{display:flex;align-items:center;justify-content:space-between;gap:12px;height:56px}
.brand{font-weight:900;letter-spacing:1px;font-size:14px;line-height:1.15;white-space:nowrap}
.brand small{display:block;font-size:10px;letter-spacing:2px;color:var(--teal);font-weight:700}
.hbtn{display:inline-flex;align-items:center;gap:6px;white-space:nowrap;background:var(--wa);color:#04140a;font-weight:800;font-size:13px;text-decoration:none;border-radius:999px;padding:8px 14px}
.nav{display:flex;gap:0;overflow-x:auto;scrollbar-width:none;padding-bottom:8px}
.nav::-webkit-scrollbar{display:none}
.nav a{flex:1 0 auto;text-align:center;text-decoration:none;font-size:13px;font-weight:700;color:var(--m);padding:7px 8px;border-radius:999px;white-space:nowrap}
.nav a.on{background:rgba(46,230,197,.12);color:var(--teal)}
@media(min-width:720px){.nav{justify-content:center}.nav a{flex:0 0 auto}}

/* common */
.sec{padding:40px 0}
@media(min-width:720px){.sec{padding:64px 0}}
.eyebrow{font-size:12px;letter-spacing:2px;text-transform:uppercase;color:var(--teal);font-weight:800}
h2{font-size:clamp(24px,6.4vw,38px);line-height:1.15;font-weight:900;letter-spacing:-.3px;margin:6px 0 8px}
.lead{color:var(--m);font-size:15px;max-width:600px}
.box{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:16px}
@media(min-width:720px){.box{padding:22px}}
.btn{display:flex;align-items:center;justify-content:center;gap:6px;text-align:center;font-weight:800;text-decoration:none;border-radius:12px;padding:13px 16px;font-size:15px;border:0;cursor:pointer;min-height:48px}
.btn.wa{background:var(--wa);color:#04140a}
.btn.gh{background:rgba(255,255,255,.07);color:#fff;border:1px solid var(--line)}
.note{font-size:12px;color:var(--m2);margin-top:12px}
.fx{opacity:0;transform:translateY(12px);transition:opacity .5s ease,transform .5s ease}
.fx.in{opacity:1;transform:none}

/* hero */
.hero{padding:16px 0 8px}
.hero .grid{display:grid;gap:18px}
@media(min-width:880px){.hero .grid{grid-template-columns:1.15fr 1fr;align-items:center;gap:36px}.hero{padding:40px 0 16px}}
.hpic{position:relative;aspect-ratio:16/10;border-radius:var(--r);overflow:hidden;background:var(--card)}
.hpic img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:0;transition:opacity 1s ease}
.hpic img.on{opacity:1}
.hpic .cap{position:absolute;left:10px;bottom:10px;font-size:12px;font-weight:700;background:rgba(0,0,0,.55);padding:4px 10px;border-radius:999px}
.hero h1{font-size:clamp(28px,7.6vw,48px);line-height:1.1;font-weight:900;letter-spacing:-.5px}
.hero h1 em{font-style:normal;color:var(--teal)}
.hero p{color:var(--m);margin:10px 0 16px;font-size:16px}
.hero .cta{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:16px}
.stat{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:10px;text-align:center}
.stat b{display:block;font-size:17px;white-space:nowrap}
.stat span{font-size:11px;color:var(--m);line-height:1.3;display:block}

/* model */
.chips{display:flex;gap:8px;overflow-x:auto;scrollbar-width:none;margin:16px -16px 16px;padding:0 16px}
.chips::-webkit-scrollbar{display:none}
@media(min-width:720px){.chips{flex-wrap:wrap;margin:18px 0;padding:0}}
.chip{flex:0 0 auto;border:1px solid var(--line);background:var(--card);border-radius:999px;padding:8px 14px;font-size:13px;font-weight:700;color:#cbd5e1;cursor:pointer;white-space:nowrap}
.chip.on{background:var(--teal);border-color:var(--teal);color:#03231e}
.grid-m{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
@media(min-width:720px){.grid-m{grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}}
@media(min-width:1000px){.grid-m{grid-template-columns:repeat(4,minmax(0,1fr))}}
.mc{display:flex;flex-direction:column;background:var(--card);border:1px solid var(--line);border-radius:14px;overflow:hidden;cursor:pointer;text-align:left;padding:0;transition:border-color .2s,transform .2s}
.mc:hover{border-color:rgba(46,230,197,.5);transform:translateY(-2px)}
.mc.hide{display:none}
.mc .ph{position:relative;aspect-ratio:4/3;background:#0b111b}
.mc .ph img{width:100%;height:100%;object-fit:cover}
.mc .bdg{position:absolute;top:8px;left:8px;font-size:10px;font-weight:800;letter-spacing:.5px;padding:3px 8px;border-radius:999px;background:#fef3c7;color:#6b4e00}
.mc .bd{padding:10px 12px 12px;display:flex;flex-direction:column;gap:2px;flex:1}
.mc h3{font-size:15px;font-weight:800;line-height:1.25}
.mc .ty{font-size:12px;color:var(--m);line-height:1.35}
.mc .pr{margin-top:auto;padding-top:8px;font-size:14px;font-weight:800;color:var(--teal)}
.mc .pr small{display:block;font-size:10px;font-weight:600;color:var(--m2)}
.cnt{font-size:13px;color:var(--m);margin-bottom:10px}

/* carousel */
.car{position:relative;margin:0 -16px}
@media(min-width:720px){.car{margin:0}}
.trk{display:flex;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;-webkit-overflow-scrolling:touch;overscroll-behavior-x:contain}
.trk::-webkit-scrollbar{display:none}
.sl{flex:0 0 100%;scroll-snap-align:center;scroll-snap-stop:always;padding:0 16px;display:flex}
@media(min-width:720px){.sl{padding:0 2px}}
.sc{flex:1;display:grid;background:var(--card);border:1px solid var(--line);border-radius:18px;overflow:hidden}
@media(min-width:880px){.sc{grid-template-columns:1.25fr 1fr}}
.sc .ph{position:relative;aspect-ratio:16/10;background:#0b111b}
@media(min-width:880px){.sc .ph{aspect-ratio:auto;min-height:380px}}
.sc .ph img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.sc .bdg{position:absolute;top:10px;left:10px;font-size:11px;font-weight:800;letter-spacing:.5px;padding:4px 10px;border-radius:999px;background:rgba(0,0,0,.6);border:1px solid var(--line)}
.sc .bdg.in{background:#fef3c7;color:#6b4e00;border-color:#fde68a}
.b360{position:absolute;right:10px;bottom:10px;display:inline-flex;align-items:center;gap:6px;border:0;border-radius:999px;padding:8px 14px;font-size:13px;font-weight:800;background:#fff;color:#0b1320;cursor:pointer;box-shadow:0 6px 18px rgba(0,0,0,.35)}
.sc .bd{padding:16px;display:flex;flex-direction:column;gap:10px}
@media(min-width:880px){.sc .bd{padding:24px}}
.sc h3{font-size:24px;font-weight:900;line-height:1.15}
.sc .ds{font-size:14px;color:var(--m)}
.tt{display:flex;flex-wrap:wrap;gap:6px}
.tt button{border:1px solid var(--line);background:var(--card2);border-radius:999px;padding:7px 12px;font-size:13px;font-weight:700;color:#cbd5e1;cursor:pointer}
.tt button.on{background:var(--teal);border-color:var(--teal);color:#03231e}
.pz small{display:block;font-size:12px;color:var(--m)}
.pz b{font-size:26px;font-weight:900;color:var(--teal);line-height:1.2}
.pz b.ind{font-size:20px;color:var(--gold)}
.sp{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.sp div{background:var(--card2);border-radius:10px;padding:9px 10px}
.sp b{display:block;font-size:14px}
.sp span{font-size:11px;color:var(--m)}
.sc .btns{grid-template-columns:1fr;margin-top:auto}
@media(min-width:420px){.sc .btns.two{grid-template-columns:1.4fr 1fr}}
.cn{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:12px}
.ar{width:44px;height:44px;flex:0 0 44px;border-radius:50%;border:1px solid var(--line);background:var(--card);color:#fff;font-size:20px;cursor:pointer}
.ci{flex:1;text-align:center;font-size:13px;color:var(--m);min-width:0}
.ci b{color:#fff}
.dt{display:flex;gap:5px;justify-content:center;margin-top:6px}
.dt i{width:6px;height:6px;border-radius:9px;background:#334155;transition:width .25s,background .25s}
.dt i.on{width:18px;background:var(--teal)}
.sw{font-size:12px;color:var(--m2);text-align:center;margin-top:8px}
/* 360 */
.v3{position:fixed;inset:0;z-index:95;background:#05080d;display:none;flex-direction:column}
.v3.open{display:flex}
.v3 .tp{display:flex;align-items:center;justify-content:space-between;padding:12px 16px}
.v3 .tp b{font-size:16px}
.v3 .x{width:40px;height:40px;border-radius:50%;border:0;background:rgba(255,255,255,.1);color:#fff;font-size:18px;cursor:pointer}
.v3 .st{flex:1;position:relative;touch-action:pan-y;cursor:grab;user-select:none;-webkit-user-select:none;display:flex;align-items:center;justify-content:center}
.v3 .st:active{cursor:grabbing}
.v3 .st img{max-width:100%;max-height:100%;object-fit:contain;pointer-events:none}
.v3 .hn{position:absolute;left:50%;bottom:18px;transform:translateX(-50%);font-size:13px;color:#cbd5e1;background:rgba(0,0,0,.5);padding:6px 14px;border-radius:999px;white-space:nowrap}
.v3 .ld{position:absolute;inset:auto 0 50% 0;text-align:center;color:var(--m);font-size:13px}
.v3 input{margin:0 16px 18px;width:calc(100% - 32px)}
/* sheet */
.sheet{position:fixed;inset:0;z-index:90;visibility:hidden}
.sheet .ov{position:absolute;inset:0;background:rgba(0,0,0,.65);opacity:0;transition:opacity .25s}
.sheet .pn{position:absolute;left:0;right:0;bottom:0;max-height:90svh;overflow:auto;background:var(--card);border-radius:20px 20px 0 0;transform:translateY(100%);transition:transform .3s ease;overscroll-behavior:contain}
@media(min-width:720px){.sheet .pn{left:50%;right:auto;bottom:auto;top:50%;width:540px;border-radius:20px;transform:translate(-50%,-40%);opacity:0;transition:transform .3s,opacity .3s}}
.sheet.open{visibility:visible}.sheet.open .ov{opacity:1}.sheet.open .pn{transform:none}
@media(min-width:720px){.sheet.open .pn{transform:translate(-50%,-50%);opacity:1}}
.pn .ph{aspect-ratio:16/9;position:relative;background:#0b111b}
.pn .ph img{width:100%;height:100%;object-fit:cover}
.pn .x{position:absolute;top:10px;right:10px;width:38px;height:38px;border-radius:50%;border:0;background:rgba(0,0,0,.6);color:#fff;font-size:18px;cursor:pointer}
.pn .c{padding:16px 16px 22px}
.pn h3{font-size:22px;font-weight:900;margin-top:2px}
.pn .lead{font-size:14px;margin-top:4px}
.specs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:14px 0}
.specs div{background:var(--card2);border-radius:10px;padding:10px}
.specs b{display:block;font-size:15px}
.specs span{font-size:12px;color:var(--m)}
.tipe{list-style:none;margin:0 0 14px;font-size:14px}
.tipe li{display:flex;justify-content:space-between;gap:12px;border-bottom:1px solid var(--line);padding:9px 0}
.tipe li span{color:#cbd5e1}
.tipe li b{text-align:right}
.btns{display:grid;gap:8px}

/* hemat (sesuai /kalkulator-hemat/) */
.hk{display:grid;gap:14px;margin-top:18px}
@media(min-width:880px){.hk{grid-template-columns:minmax(0,1fr) minmax(0,1fr);align-items:start;gap:20px}}
.tg2{display:grid;grid-template-columns:1fr 1fr;gap:6px;background:var(--card2);padding:4px;border-radius:12px;margin-bottom:14px}
.tg2 button{border:0;background:transparent;border-radius:9px;padding:11px 6px;font-size:14px;font-weight:800;color:#cbd5e1;cursor:pointer}
.tg2 button.on{background:var(--teal);color:#03231e}
.fl{margin-bottom:12px}
.fl label{display:block;font-size:13px;font-weight:700;color:#cbd5e1;margin-bottom:6px}
.fl input,.fl select{width:100%;background:var(--card2);color:#fff;border:1px solid var(--line);border-radius:12px;padding:12px 14px;font:inherit;font-size:16px;-webkit-appearance:none;appearance:none}
.fl input:focus,.fl select:focus{outline:none;border-color:var(--teal)}
.fl .sel:after{top:50%}
.fl small{display:block;font-size:11px;color:var(--m2);margin-top:5px}
.r2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.kons{display:flex;justify-content:space-between;align-items:center;gap:10px;background:rgba(46,230,197,.07);border:1px dashed rgba(46,230,197,.35);border-radius:12px;padding:10px 14px;margin-bottom:12px}
.kons span{font-size:12px;color:var(--m)}
.kons b{font-size:16px;white-space:nowrap}
.yr{border-radius:16px;padding:18px;background:linear-gradient(160deg,#0b3b34,#071f1b);border:1px solid rgba(46,230,197,.25)}
.yr span{font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#a7f3d0;font-weight:800}
.yr b{display:block;font-size:clamp(30px,8.5vw,44px);font-weight:900;color:var(--teal);line-height:1.1;margin:4px 0}
.yr p{font-size:13px;color:#cbd5e1}
.mn{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:10px}
.mn div{background:var(--card2);border-radius:12px;padding:12px;min-width:0}
.mn span{font-size:11px;letter-spacing:1px;text-transform:uppercase;color:var(--m);font-weight:800;display:block}
.mn b{font-size:clamp(16px,4.6vw,20px);font-weight:900;white-space:nowrap}
.rc{width:100%;border-collapse:collapse;font-size:13px;margin-top:12px;font-variant-numeric:tabular-nums}
.rc th{font-size:11px;letter-spacing:.5px;text-transform:uppercase;color:var(--m2);font-weight:800;text-align:left;padding:0 0 8px}
.rc th:not(:first-child),.rc td:not(:first-child){text-align:right}
.rc td{padding:9px 0;border-top:1px solid var(--line)}
.rc td:nth-child(3){color:var(--teal);font-weight:700}
.rc tr.df td{font-weight:900;color:#4ade80}
.hk .btns{margin-top:14px}
@media(min-width:420px){.hk .btns{grid-template-columns:1fr 1fr}.hk .btns .wa{grid-column:1/-1}}
/* denza */
.dz{background:linear-gradient(180deg,var(--bg),#0d0b07 50%,var(--bg))}
.dz .lay{display:grid;gap:18px}
@media(min-width:880px){.dz .lay{grid-template-columns:1.3fr 1fr;align-items:center;gap:36px}}
.dz .pic{border-radius:var(--r);overflow:hidden;aspect-ratio:16/10;background:#000}
.dz .pic img{width:100%;height:100%;object-fit:cover;object-position:60% 55%}
.dz .eyebrow{color:var(--gold)}
.dz .price{font-size:24px;font-weight:900;color:var(--gold);margin:6px 0 14px}
.dz ul{list-style:none;display:grid;gap:6px;margin:12px 0 16px;color:#d6cbb8;font-size:14px}
.dz ul li:before{content:"✓ ";color:var(--gold);font-weight:900}

/* kredit */
.kr .box{margin-top:18px}
@media(min-width:880px){.kr .lay{display:grid;grid-template-columns:1fr 1.2fr;gap:36px;align-items:start}.kr .box{margin-top:0}}
.f{display:block;font-size:13px;color:#cbd5e1;font-weight:700;margin-bottom:6px}
.sel{position:relative}
.sel select{width:100%;appearance:none;-webkit-appearance:none;background:var(--card2);color:#fff;border:1px solid var(--line);border-radius:12px;padding:12px 40px 12px 14px;font:inherit;font-size:15px;font-weight:700}
.sel:after{content:"▾";position:absolute;right:14px;top:50%;transform:translateY(-50%);color:var(--m);pointer-events:none}
.seg{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;background:var(--card2);padding:4px;border-radius:12px;margin-top:14px}
.seg button{border:0;background:transparent;border-radius:9px;padding:10px 4px;font-size:14px;font-weight:800;color:#cbd5e1;cursor:pointer}
.seg button.on{background:var(--teal);color:#03231e}
.seg button:disabled{opacity:.3;cursor:not-allowed}
.res{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:14px}
.res div{background:var(--card2);border-radius:12px;padding:12px;min-width:0}
.res span{font-size:12px;color:var(--m);display:block}
.res b{font-size:clamp(16px,4.4vw,22px);font-weight:900;white-space:nowrap}
.res b small{font-size:12px;font-weight:600;color:var(--m)}
.res .t b{color:var(--teal)}
.ten{width:100%;border-collapse:collapse;margin-top:14px;font-size:14px}
.ten th{text-align:left;font-size:12px;color:var(--m2);font-weight:700;padding:0 0 6px}
.ten th:last-child,.ten td:last-child{text-align:right}
